  if (!ok) return `<div class="wrap">${back('org-' + oid, o.n, 'Page')}<div class="empty"><h2>${own ? 'Finish your profile to unlock your page' : 'This organisation hasn’t set up its page yet'}</h2>${own ? `<p>${pct(oid)}% done.</p><a class="btn p" href="#setup">Continue setting up</a>` : `<a class="btn s" href="#org-${esc(oid)}">See their listing</a>`}</div></div>`;
  const d = demo ? { tagline: 'Example tagline: one line about what you do', about: o.d || '' } : orgData(oid), url = LIVE_BASE + '#page-' + oid;
  L.track('org_page_view', { org: oid, demo });
