const topHost = () => ''; const _topHostOld = () => { const m = {}; hoursAll().filter(h => h.status === 'confirmed' && (h.date || '').startsWith(monthKey())).forEach(h => m[h.orgId] = (m[h.orgId] || 0) + (+h.hrs || 0)); const top = Object.entries(m).sort((a, b) => b[1] - a[1])[0]; return top && top[1] > 0 ? top[0] : ''; };
