/* =====================================================================
   3) REMIND ME
   ===================================================================== */
const rems = () => store.get('reminders', []);
const OFFS = [[7, '1 week before'], [1, '1 day before'], [0, 'On the day']];
const dateFor = key => { const [t, ...r] = key.split(':'), id = r.join(':'); if (t === 'fund') return (L.FUNDS.find(f => f.id === id) || {}).dl || ''; if (t === 'event') return (H.EV.find(e => slug(e.t + '-' + (e.s || '')) === id) || {}).s || ''; if (t === 'deal') return ((window.DEALS || []).find(d => d.id === id) || {}).ex || ''; return ''; };
const bellBtn = (key, title, href) => { const on = rems().some(r => r.key === key); return `<button class="savebtn bellbtn ${on ? 'on' : ''}" data-remind="${esc(key)}" data-rtitle="${esc(title)}" data-rhref="${esc(href)}" aria-label="${on ? 'Reminder set' : 'Remind me'}" title="${on ? 'Reminder set' : 'Remind me'}">${si('bell')}</button>`; };
const remindModal = (key, title, href) => { const r = rems().find(x => x.key === key), dt = r?.date || dateFor(key), days = dt ? Math.round((new Date(dt) - new Date(ISO(TODAY))) / DAY) : null;
  modal(`<div class="mhead"><h3>Remind me</h3>${closeX}</div><p><b>${esc(title)}</b>${dt ? `<br><span class="note">${key.startsWith('fund') ? 'Closes' : key.startsWith('deal') ? 'Ends' : 'On'} ${fmtDate(dt)}</span>` : ''}</p>
  <form class="form" id="remForm" data-key="${esc(key)}" data-title="${esc(title)}" data-href="${esc(href)}">${dt ? `<input type="hidden" name="date" value="${dt}">` : `<label class="f">Date<input class="in" type="date" name="date" required min="${ISO(TODAY)}" value="${esc(r?.date || '')}"></label>`}
  <fieldset class="f"><legend>When should we remind you?</legend><div class="seg radios">${OFFS.map(([d, t]) => `<label><input type="checkbox" name="off" value="${d}" ${(r ? r.offs.includes(d) : d === 1) ? 'checked' : ''} ${days != null && days < d ? 'disabled' : ''}> ${t}</label>`).join('')}</div></fieldset>
  <div class="row"><button class="btn p">Save reminder</button>${r ? '<button type="button" class="btn s" data-remdel>Remove</button>' : ''}</div><p class="note">${LIVE ? 'We’ll email you, and send a phone notification if you’ve allowed them.' : 'Preview: reminders show on this device when you open the hub. On the live site they come by email or phone notification.'}</p></form>`); };
document.addEventListener('click', e => { const b = e.target.closest('[data-remind]'); if (b) { e.preventDefault(); e.stopPropagation(); remindModal(b.dataset.remind, b.dataset.rtitle, b.dataset.rhref); }
  const d = e.target.closest('[data-remdel]'); if (d) { const k = $('#remForm').dataset.key; store.set('reminders', rems().filter(r => r.key !== k)); closeModal(); toast('Reminder removed'); L.render(); }
  const x = e.target.closest('[data-remx]'); if (x) { store.set('reminders', rems().filter(r => r.key !== x.dataset.remx)); L.render(); } }, true);
document.addEventListener('submit', e => { const f = e.target; if (f.id !== 'remForm') return; e.preventDefault(); e.stopImmediatePropagation(); const fd = new FormData(f), offs = fd.getAll('off').map(Number); if (!offs.length) return toast('Pick at least one');
  const l = rems().filter(r => r.key !== f.dataset.key); l.push({ key: f.dataset.key, title: f.dataset.title, href: f.dataset.href, date: fd.get('date'), offs, shown: [], at: now() }); store.set('reminders', l); closeModal(); toast('Reminder set'); L.track('reminder_set', { key: f.dataset.key }); L.render(); }, true);
V.reminders = () => { const l = rems().sort((a, b) => a.date.localeCompare(b.date));
  return `<div class="wrap">${back('account', 'My dashboard', 'My reminders')}<h1>My reminders</h1><p class="lede">Deadlines and dates you asked us to remind you about. Tap the bell on any fund, event, offer, course or activity to add one.</p>
  ${l.length ? `<ul class="remlist">${l.map(r => { const past = r.date < ISO(TODAY); return `<li class="${past ? 'past' : ''}">${si('bell')}<div><a href="#${esc(r.href)}"><b>${esc(r.title)}</b></a><span>${fmtDate(r.date)} · ${r.offs.map(o => OFFS.find(x => x[0] === o)[1].toLowerCase()).join(', ')}</span></div><button class="ib sm" data-remind="${esc(r.key)}" data-rtitle="${esc(r.title)}" data-rhref="${esc(r.href)}" aria-label="Edit">${si('clock')}</button><button class="ib sm" data-remx="${esc(r.key)}" aria-label="Remove">${si('x')}</button></li>`; }).join('')}</ul>` : '<div class="empty">No reminders yet. Tap the bell on a fund, event or offer.</div>'}</div>`; };
const dueCheck = () => { const t = ISO(TODAY), l = rems(); let shown = null; l.forEach(r => r.offs.forEach(o => { const due = ISO(new Date(new Date(r.date) - o * DAY)); if (due <= t && r.date >= t && !r.shown.includes(o) && !shown) { shown = { r, o }; r.shown.push(o); } })); if (!shown) return; store.set('reminders', l);
  const { r, o } = shown, when = o === 0 ? 'today' : o === 1 ? 'tomorrow' : 'in a week'; const w = $('#main > .wrap'); if (!w) return;
  w.insertAdjacentHTML('afterbegin', `<div class="remnote" role="status">${si('bell')}<span><b>Reminder:</b> ${esc(r.title)} is ${when} (${fmtDate(r.date)}).</span><a class="btn s sm" href="#${esc(r.href)}">Open</a><button class="ib sm" data-close-rem aria-label="Dismiss">${si('x')}</button></div>`); };
document.addEventListener('click', e => { const b = e.target.closest('[data-close-rem]'); if (b) b.closest('.remnote').remove(); });

