const coldSub = () => store.get('coldsub', null);
const coldMsg = () => `Emergency shelter and warm spaces are open in Luton tonight because of the cold. If you or someone you know needs somewhere warm, here’s where to go: hub.smrdigital.co.uk/#help. If someone is sleeping rough, tell StreetLink (streetlink.org.uk). In an emergency, call 999.`;
const coldBlock = () => { const s = coldSub(), a = store.get('coldalert', null), live = a && now() - a.at < 48 * 36e5;
  return `<section class="coldbox">${si('snow', 'big')}<div><b>Cold weather alerts for organisations</b><p>Get alerted when emergency shelter or warm spaces open, so you can signpost the people you support. Each alert comes with a ready-to-forward message and a poster.</p>${live ? `<p class="coldlive"><b>Alert active:</b> ${esc(a.text || 'Emergency shelter and warm spaces are open.')} <button class="linkbtn" data-coldkit>Forward message & poster</button></p>` : ''}</div>
  <div class="coldact">${s ? `<span class="tag ok">${si('check')} Alerts on${s.email ? ' for ' + esc(s.email) : ''}</span><button class="linkbtn" data-coldoff>Turn off</button>` : `<button class="btn p sm" data-coldon>Alert my organisation</button>`}<button class="linkbtn" data-coldkit>See the message & poster</button></div></section>`; };
const coldKit = () => modal(`<div class="mhead"><h3>Ready to forward</h3>${closeX}</div><p class="note">Pass this on to the people you support, on WhatsApp, by text or on your noticeboard.</p><div class="msg" id="coldTxt">${esc(coldMsg())}</div><div class="row" style="margin-top:10px">${copyBtn('#coldTxt', 'Copy message')}<a class="btn s sm" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent(coldMsg())}">${ic('wa')} WhatsApp</a></div>
  <h3 style="margin-top:18px">Poster</h3><div class="poster cold" id="poster" style="--bc:#1C6FB8"><div class="pst-top"><h2>Somewhere warm tonight</h2><p>Emergency shelter and warm spaces are open in Luton because of the cold.</p></div><div class="pst-qr">${qrSVG('https://hub.smrdigital.co.uk/#help', 240)}</div><p class="pst-url">Scan for places, times and how to get there</p><p class="pst-url">Sleeping rough? StreetLink: streetlink.org.uk · Emergency: 999</p><p class="pst-foot">Shared by your local organisation · Luton Community Hub</p></div><p class="note">Check times and places on the day before you put it up.</p><button class="btn p sm" data-printposter>${si('print')} Print or save as PDF</button>`);
document.addEventListener('click', async e => { const b = e.target.closest('[data-coldon],[data-coldoff],[data-coldkit],[data-coldsend]'); if (!b) return; e.preventDefault();
  if ('coldkit' in b.dataset) return coldKit();
  if ('coldoff' in b.dataset) { store.set('coldsub', null); toast('Cold weather alerts off'); return L.render(); }
  if ('coldon' in b.dataset) { if (!prof()) return needAcct('Cold weather alerts are for organisations, so they need a free account.'); const s = { email: prof().email || '', org: prof().org || '', at: now() }; store.set('coldsub', s); L.submit('cold-alert-org', { ...s, orgId: myId(), title: 'Cold weather alerts: ' + (s.org || s.email) }, '', { title: 'Cold weather alerts on', text: 'We’ll alert your organisation when emergency shelter or warm spaces open, with a message and poster to pass on.' }); return; }
  if ('coldsend' in b.dataset) { const t = $('#coldText')?.value || 'Emergency shelter and warm spaces are open tonight.'; store.set('coldalert', { at: now(), text: t }); toast('Alert sent (preview stand-in)'); L.render(); } });

