const NUMSRC = [['ONS: How life has changed in Luton, Census 2021', 'https://www.ons.gov.uk/visualisations/censusareachanges/E06000032'], ['Luton Council: Indices of Deprivation 2025 briefing', 'https://www.luton.gov.uk/sites/default/files/2026-03/IMD-2025-briefing-luton-2025.pdf'], ['Luton Council: This is Luton (JSNA)', 'https://www.luton.gov.uk/sites/default/files/2026-02/jsna-this-is-Luton.pdf'], ['Luton Council: Key facts about Luton', 'https://www.luton.gov.uk/council-elections/statistics-census-information/key-facts-about-luton']];
V.numbers = () => `<div class="wrap">${back('fundsup', 'Funding support', 'Luton in numbers')}<h1>Luton in numbers</h1><p class="lede">Official figures for your bids, reports and appeals. Each one comes with its source and year, so you can copy it straight into an application.</p>
  <p class="notice">Figures checked on 24 November 2026. Always quote the source, and check the funder hasn’t asked for a different year or area.</p>
  ${NUM.map(([g, items], gi) => `<section class="band" style="padding-top:12px"><h2>${g}</h2><div class="grid">${items.map(([t, f, s], i) => `<div class="card numc"><span class="tag">${esc(t)}</span><p class="numf">${esc(f)}</p><p class="note">Source: ${esc(s)}</p><button class="btn s sm" data-copynum="${gi}-${i}">${ic('copy')} Copy for your bid</button></div>`).join('')}</div></section>`).join('')}
  <h3>Sources</h3><ul class="srcs">${NUMSRC.map(([t, u]) => `<li><a href="${u}" target="_blank" rel="noopener">${esc(t)}</a></li>`).join('')}</ul>
  <p class="note">Need a figure for your ward or service area? Ward-level data is on Luton Council’s statistics pages. Ask us and we’ll point you to it.</p></div>`;
document.addEventListener('click', async e => { const b = e.target.closest('[data-copynum]'); if (!b) return; const [g, i] = b.dataset.copynum.split('-').map(Number), [, f, s] = NUM[g][1][i], txt = `${f} (Source: ${s})`; try { await navigator.clipboard.writeText(txt); toast('Copied with its source'); } catch (er) { modal(`<div class="mhead"><h3>Copy this</h3>${closeX}</div><div class="msg">${esc(txt)}</div>`); } L.track('number_copied', { k: b.dataset.copynum }); });

V.partners = () => { const l = L.appr('partner-post');
  return `<div class="wrap">${back('fundsup', 'Funding support', 'Partner up')}<h1>Partner up</h1><p class="lede">Many funders favour joint bids. Post what you’re planning or the partner you need, or offer to join someone else’s bid.</p>
  <div class="row" style="margin:12px 0"><button class="btn p" data-partnerpost="seek">Find a partner</button><button class="btn s" data-partnerpost="offer">Offer to partner</button></div>
  <div class="grid">${l.length ? l.map(a => `<div class="card"><span class="tag ${a.data.mode === 'offer' ? 'ok' : ''}">${a.data.mode === 'offer' ? 'Offering to partner' : 'Looking for a partner'}</span><h3>${esc(a.data.title)}</h3><p>${esc(a.data.details || '')}</p><dl class="dl sm2">${a.data.fund ? `<dt>Fund</dt><dd>${esc(a.data.fund)}</dd>` : ''}${a.data.deadline ? `<dt>Deadline</dt><dd>${esc(a.data.deadline)}</dd>` : ''}<dt>Posted by</dt><dd>${esc(a.data.org || '')}</dd></dl><button class="btn p sm" data-xq="enquiry" data-pre='${esc(JSON.stringify({ orgId: a.data.orgId || '' }))}'>Get in touch</button></div>`).join('') : '<div class="empty">No posts yet. Be the first: say what you’re planning and who you’d like to work with.</div>'}</div>
  <p class="note" style="margin-top:12px">Posts need a free account and are checked by the hub team before they show.</p></div>`; };
document.addEventListener('click', e => { const b = e.target.closest('[data-partnerpost]'); if (!b) return; if (!prof()) return needAcct('Posting on Partner up needs a free account, so partners know who you are.'); const m = b.dataset.partnerpost;
  modal(`<div class="mhead"><h3>${m === 'offer' ? 'Offer to partner' : 'Find a partner'}</h3>${closeX}</div><form class="form" id="partnerForm" data-mode="${m}"><label class="f">${m === 'offer' ? 'What you can bring' : 'What you’re planning'}<input class="in" name="title" required placeholder="${m === 'offer' ? 'e.g. A hall, youth workers, and links with 3 schools' : 'e.g. A holiday food and fun programme in Biscot'}"></label><label class="f">Details<textarea class="in" name="details" required></textarea></label><div class="two"><label class="f">Fund (if known)<input class="in" name="fund"></label><label class="f">Deadline<input class="in" type="date" name="deadline"></label></div><button class="btn p">Send for approval</button></form>`); });
document.addEventListener('submit', e => { const f = e.target; if (f.id !== 'partnerForm') return; e.preventDefault(); e.stopImmediatePropagation(); const o = L.formData(f); o.mode = f.dataset.mode; o.org = prof()?.org || ''; o.orgId = myId(); pubAct(myId(), 'Partner up post'); L.submit('partner-post', o, '', { title: 'Sent for approval', text: 'Your post will show on Partner up once it’s checked.' }); }, true);

const BIDCK = f => [
  ['Check you’re eligible', `Who can apply: ${f.ot?.length ? 'check your organisation type is on their list' : 'see the funder’s page'}.`],
  ['Check the deadline and process', f.dl ? `Closes ${fmtDate(f.dl)}. ${f.win ? f.win.split(';')[0] : ''}` : (f.win || 'See the funder’s page for dates.')],
  ['Ask for the right amount', f.at || 'Match the amount to the fund’s range.'],
  ['Read the guidance in full', 'Including what they won’t fund.'],
  ['Show the need with evidence', 'Use local figures with their source. See Luton in numbers.'],
  ['Say what will change', 'Clear outcomes: how many people, what difference, by when.'],
  ['Budget adds up', 'Every line explained. Include fair core costs if allowed.'],
  ['Policies ready', 'Safeguarding, equality and data protection, if asked for. See the Policy library.'],
  ['Accounts and governing document', 'Latest accounts, and your constitution or articles.'],
  ['Bank details in the organisation’s name', 'Most funders need a bank account in the organisation’s name with two signatories.'],
  ['Someone else has read it', 'A fresh pair of eyes catches gaps and typos.'],
  ['Saved a copy', 'Keep what you sent and the date you sent it.'],
];
document.addEventListener('click', e => { const b = e.target.closest('[data-bidck]'); if (!b) return; e.preventDefault(); const f = L.FUNDS.find(x => x.id === b.dataset.bidck); if (!f) return; const tk = (store.get('bidck', {})[f.id]) || [];
  modal(`<div class="mhead"><div><span class="note">Before you submit</span><h3 style="margin:2px 0 0">${esc(f.n)}</h3></div>${closeX}</div><div class="su-bar"><i id="bidBar" style="width:${tk.length / 12 * 100}%"></i></div><ul class="bidck" data-fund="${esc(f.id)}">${BIDCK(f).map(([t, d], i) => `<li><label><input type="checkbox" data-bidi="${i}" ${tk.includes(i) ? 'checked' : ''}><span><b>${esc(t)}</b><small>${esc(d)}</small></span></label></li>`).join('')}</ul><p class="note">${prof() ? 'Your ticks are saved.' : 'Sign in to save your ticks.'} Always follow the funder’s own guidance.</p><div class="row"><a class="btn s sm" href="#writer" data-close>Help me write it</a>${okUrl(f.url) ? `<a class="btn s sm" href="${esc(okUrl(f.url))}" target="_blank" rel="noopener">Funder’s page</a>` : ''}</div>`); });
document.addEventListener('change', e => { const c = e.target; if (c.dataset.bidi == null) return; const id = c.closest('[data-fund]').dataset.fund, m = store.get('bidck', {}), l = $$('[data-bidi]', c.closest('ul')).filter(x => x.checked).map(x => +x.dataset.bidi); if (prof()) { m[id] = l; store.set('bidck', m); } $('#bidBar').style.width = l.length / 12 * 100 + '%'; if (l.length === 12) toast('All ticked. Good luck with your bid!'); });

/* =====================================================================
   6) SHARE EVERYWHERE
   ===================================================================== */
const PEOPLE_PAGES = ['help', 'events', 'activities', 'volunteering', 'discounts', 'youth', 'staff', 'training', 'needs', 'role', 'prayer'];
const itemLink = key => { const [t, ...r] = key.split(':'); const id = r.join(':'); if (t === 'role') return LIVE_BASE + '#role-' + id; return LIVE_BASE + '#item-' + t + '-' + id; };
const shareSheet = ({ title, text, url, head = 'Share' }) => { const full = `${text} ${url}`; L.track('share_open', { url });
  if (navigator.share && matchMedia('(pointer:coarse)').matches) { navigator.share({ title, text, url }).catch(() => { }); return; }
  modal(`<div class="mhead"><h3>${esc(head)}</h3>${closeX}</div><p class="note">${head.includes('organisation') || head.includes('team') ? 'Send it on by message or email.' : 'They can open it without an account.'}</p><div class="msg" id="shTxt">${esc(full)}</div>
  <div class="shgrid"><button class="shb" data-copy="#shTxt">${si('copy')}<span>Copy message</span></button><button class="shb" data-copylink="${esc(url)}">${si('link')}<span>Copy link</span></button><a class="shb" target="_blank" rel="noopener" href="https://wa.me/?text=${encodeURIComponent(full)}">${ic('wa')}<span>WhatsApp</span></a><a class="shb" target="_blank" rel="noopener" href="https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}">${si('share')}<span>Facebook</span></a><a class="shb" target="_blank" rel="noopener" href="https://x.com/intent/post?text=${encodeURIComponent(text)}&url=${encodeURIComponent(url)}">${si('share')}<span>X</span></a><a class="shb" href="mailto:?subject=${encodeURIComponent(title)}&body=${encodeURIComponent(full)}">${si('mail')}<span>Email</span></a></div>`); };
L.shareSheet = shareSheet;
const PEOPLE = ['service', 'event', 'act', 'deal', 'role', 'need', 'tr', 'winter'];
const itemInfo = key => { const [t, ...r] = key.split(':'), id = r.join(':');
  if (t === 'fund') { const f = L.FUNDS.find(x => x.id === id); return f && { title: f.n, amt: f.at }; }
  if (t === 'event') { const e = H.EV.find(x => slug(x.t + '-' + (x.s || '')) === id); return e && { title: e.t, when: e.when || e.s, where: e.where, cost: e.cost }; }
  if (t === 'deal') { const d = (window.DEALS || []).find(x => x.id === id); return d && { title: d.b + ': ' + d.o, brand: d.b, offer: d.o, student: /stu|young/i.test(JSON.stringify([d.aud, d.tabs])) }; }
  if (t === 'service') { const v = (window.NGSHELP?.S || []).find(x => (x.id || slug(x.n)) === id); return v && { title: v.n, desc: (v.d || '').split(/(?<=\.)\s/)[0] }; }
  if (t === 'act') { const w = H.WO.find(x => slug(x.t) === id); return w && { title: w.t, when: w.when, where: w.where }; }
  if (t === 'tr') { const x = L.TRAIN.find(z => slug(z.t) === id); return x && { title: x.t, cost: x.cost }; }
  if (t === 'role') { const v = (window.NGSVOL || []).find(x => String(x.id) === id); return v && { title: v.t, org: v.org, when: v.when }; }
  return null; };
const shareLabel = (key = '') => { const t = key.split(':')[0], i = itemInfo(key) || {}; if (!PEOPLE.includes(t)) return 'Share with another organisation'; if (t === 'deal') return i.student ? 'Share with your students' : 'Pass this on to your team'; if (t === 'act' || t === 'event') return 'Pass this on to your families'; if (t === 'role' || t === 'need') return 'Share with your community'; return 'Share with someone who might benefit'; };
const niceMsg = (key, title) => { const t = key.split(':')[0], i = itemInfo(key) || { title };
  if (t === 'service') return `${i.title}${i.desc ? '. ' + i.desc.replace(/\.$/, '') : ''}. Thought this might help:`;
  if (t === 'event') return `${i.title}${i.when ? ', ' + i.when : ''}${i.where ? ' at ' + i.where : ''}. Thought you might like this:`;
  if (t === 'act') return `${i.title}${i.where ? ' in ' + i.where : ''}. Something to do with the family:`;
  if (t === 'deal') return i.student ? `Students can get this at ${i.brand}: ${i.offer}. Here’s how:` : `${i.brand}: ${i.offer}. Have a look:`;
  if (t === 'role') return `Fancy volunteering? ${i.title}${i.org ? ' with ' + i.org : ''}. Here are the details:`;
  if (t === 'need') return `A local group needs help: ${i.title || title}. Can you help?`;
  if (t === 'tr') return `${/free/i.test(i.cost || '') ? 'Free course' : 'Course'}: ${i.title}. Here are the details:`;
  if (t === 'fund') return `A grant that might suit your organisation: ${i.title}${i.amt ? ' (' + i.amt.split(';')[0] + ')' : ''}. Details here:`;
  return `${title}. Have a look:`; };
document.addEventListener('click', e => { const b = e.target.closest('[data-share],[data-shareitem],[data-sharehere]'); if (!b || b.closest('.mlist')) return; e.preventDefault(); e.stopImmediatePropagation();
  if ('sharehere' in b.dataset) { const h1 = ($('#main h1')?.textContent || 'Luton Community Hub').trim(), v = L.route().v, ppl = PEOPLE_PAGES.includes(v); return shareSheet({ title: h1, text: ppl ? `${h1} in Luton. Thought this might help:` : `${h1}, free for Luton organisations on the Luton Community Hub:`, url: LIVE_BASE + location.hash, head: ppl ? 'Share with your community' : 'Send to your team or another organisation' }); }
  const card = b.closest('.card, article, .opage'), sv = card?.querySelector('[data-save]'), key = b.dataset.shareitem || sv?.dataset.save;
  if (key) { const title = sv?.dataset.stitle || b.dataset.stitle || ''; return shareSheet({ title, text: niceMsg(key, title), url: itemLink(key), head: shareLabel(key) }); }
  const raw = b.dataset.share || ''; const m = raw.match(/https?:\/\/\S+/); const url = m ? m[0] : LIVE_BASE + location.hash; const ppl = PEOPLE_PAGES.includes(L.route().v); shareSheet({ title: 'Luton Community Hub', text: (raw.replace(url, '').trim() || 'Have a look') + (ppl ? '. Thought this might help:' : ':'), url, head: ppl ? 'Share with someone who might benefit' : 'Share' }); }, true);
/* item deep links: #item-<type>-<id> */
V.item = id => { const [t, ...r] = id.split('-'), key = r.join('-'); let h = '', title = '', href = 'home';
  if (t === 'fund') { const f = L.FUNDS.find(x => x.id === key); if (f) { title = f.n; href = 'funding'; h = `<p class="note">${esc(f.by || '')}</p><p><b>${esc(f.at || '')}</b></p>${f.dl ? `<p>Closes ${fmtDate(f.dl)}</p>` : `<p class="note">${esc(f.win || '')}</p>`}<div class="row">${okUrl(f.url) ? `<a class="btn p sm" href="${esc(okUrl(f.url))}" target="_blank" rel="noopener">Funder’s page</a>` : ''}<button class="btn s sm" data-bidck="${esc(f.id)}">Before you submit</button>${bellBtn('fund:' + f.id, f.n, 'item-fund-' + f.id)}</div>`; } }
  if (t === 'event') { const e = H.EV.find(x => slug(x.t + '-' + (x.s || '')) === key); if (e) { title = e.t; href = 'events'; h = `<p><b>${esc(e.when || e.s)}</b>${e.where ? ' · ' + esc(e.where) : ''}</p><p>${esc(e.d || '')}</p><p class="note">${esc(e.cost || '')}${e.ages ? ' · ' + esc(e.ages) : ''}</p><div class="row">${okUrl(e.url) ? `<a class="btn p sm" href="${esc(okUrl(e.url))}" target="_blank" rel="noopener">Details</a>` : ''}${dirBtn(e.where, e.pc)}</div>`; } }
  if (t === 'deal') { const d = (window.DEALS || []).find(x => x.id === key); if (d) { title = d.b + ': ' + d.o; href = 'discounts'; h = `<p>${esc(d.wh || '')}</p><p class="note">${esc(d.req || '')}${d.ex ? ' · Ends ' + fmtDate(d.ex) : ''}</p><div class="row">${okUrl(d.link) ? `<a class="btn p sm" href="${esc(okUrl(d.link))}" target="_blank" rel="noopener">Find out more</a>` : ''}</div>`; } }
  if (t === 'service') { const s = (window.NGSHELP?.S || []).find(x => (x.id || slug(x.n)) === key); if (s) { title = s.n; href = 'help'; h = `<p>${esc(s.d || '')}</p>${s.a ? `<p class="note">${esc(s.a)}</p>` : ''}${s.ph || s.tel ? `<p><a href="tel:${esc(String(s.ph || s.tel).replace(/\s/g, ''))}">${esc(s.ph || s.tel)}</a></p>` : ''}<div class="row">${okUrl(s.web) ? `<a class="btn p sm" href="${esc(okUrl(s.web))}" target="_blank" rel="noopener">Details</a>` : ''}${dirBtn(s.a, s.pc)}</div>`; } }
  if (t === 'act') { const w = H.WO.find(x => slug(x.t) === key); if (w) { title = w.t; href = 'activities'; h = `<p>${esc(w.d || '')}</p><p class="note">${esc(w.when || '')} · ${esc(w.where || '')}</p><div class="row">${okUrl(w.url) ? `<a class="btn p sm" href="${esc(okUrl(w.url))}" target="_blank" rel="noopener">Details</a>` : ''}${dirBtn(w.where, w.pc)}</div>`; } }
  if (t === 'tr') { const x = L.TRAIN.find(z => slug(z.t) === key); if (x) { title = x.t; href = 'training'; h = `<p class="note">${esc(x.by)}</p><p>${esc(x.fmt || '')}</p><p><b>${esc(x.cost || '')}</b></p><p class="note">${esc(x.who || '')}</p>${okUrl(x.u) ? `<a class="btn p sm" href="${esc(okUrl(x.u))}" target="_blank" rel="noopener">Find out more</a>` : ''}`; } }
  if (!title) return `<div class="wrap">${back('home', 'Home')}<div class="empty">This item has ended or moved. <a href="#home">Back to the hub</a></div></div>`;
  const solo = PEOPLE.includes(t); L.track('item_view', { t, solo });
  if (solo) return `<div class="wrap solowrap"><article class="card itemc"><h1>${esc(title)}</h1>${h}<div class="row" style="margin-top:14px"><button class="btn o sm" data-shareitem="${esc(t + ':' + key)}" data-stitle="${esc(title)}">${si('share')} Send to someone</button></div><p class="note" style="margin-top:14px">Details can change, so please check with them before you go.</p></article>${L.POWERED}</div>`;
  return `<div class="wrap" style="max-width:760px">${back(href, META[href]?.[1] || 'Back', title)}<article class="card itemc"><h1 style="font-size:clamp(26px,4vw,36px)">${esc(title)}</h1>${h}<div class="row" style="margin-top:12px"><button class="btn o sm" data-shareitem="${esc(t + ':' + key)}" data-stitle="${esc(title)}">${si('share')} Share with another organisation</button><a class="btn s sm" href="#${href}">See more like this</a></div></article></div>`; };
const dirBtn = (where, pc) => where || pc ? `<a class="btn s sm" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent((where || '') + ' ' + (pc || '') + ' Luton')}">${ic('map')} Directions</a>` : '';

