const FH = () => window.FHIST || [];
const SINCE = 2021, NAMED = 'named on organisation website (no date or amount)';
const yEnd = y => { const m = String(y || '').match(/(\d{4})(?!.*\d{4})/); return m ? +m[1] : null; };
const yStart = y => { const m = String(y || '').match(/(\d{4})/); return m ? +m[1] : null; };
const recent = h => { const e = yEnd(h.year); return e != null && e >= SINCE; };
const gbp = n => n == null ? '' : '£' + Math.round(n).toLocaleString('en-GB');
const nrm = s => String(s || '').toLowerCase().replace(/&/g, 'and').replace(/^the /, '').replace(/\s+/g, ' ');
const openFundFor = f => { const k = nrm(f).slice(0, 16); return (L.FUNDS || []).find(x => x.st !== 'closed' && nrm(x.by).includes(k)); };
const srcLink = u => okUrl(u) ? `<a href="${esc(u)}" target="_blank" rel="noopener">source</a>` : '';
const whenTxt = h => { const s = yStart(h.year), e = yEnd(h.year); return !s ? '' : s === e ? String(s) : `${s}–${e}`; };

/* panel on listings and organisation pages */
const funderPanel = id => {
  const all = FH().filter(h => h.org === id), dated = all.filter(recent), named = all.filter(h => h.type === NAMED);
  if (!dated.length && !named.length) return `<div class="dlbox fhp"><h3>Who has funded them (last 5 years)</h3><p class="note">We couldn’t find published grant records for this organisation yet. Many groups are funded in ways that aren’t published online. If this is your organisation, you can add your funders when you set up your profile.</p></div>`;
  const row = h => `<li><b>${esc(h.funder)}</b>${h.programme ? ' · ' + esc(h.programme) : ''}<span class="note"> · ${h.type && h.type.startsWith('aggregate') ? `${h.grants || ''} grant${h.grants === 1 ? '' : 's'}${h.amount ? ', ' + gbp(h.amount) + ' in total' : ''} between ${whenTxt(h)}` : `${esc(String(h.year || ''))}${h.amount ? ' · ' + gbp(h.amount) : ''}`}</span> ${srcLink(h.source)}</li>`;
  const pre = dated.some(h => yStart(h.year) < SINCE);
  return `<div class="dlbox fhp"><h3>Who has funded them (last 5 years)</h3>
  ${dated.length ? `<ul class="pfr">${dated.sort((a, z) => (z.amount || 0) - (a.amount || 0)).map(row).join('')}</ul>${pre ? `<p class="note">Some totals come from a published summary that also counts grants from before ${SINCE}. The dates show the full range.</p>` : ''}` : ''}
  ${named.length ? `<p class="note" style="margin-top:10px"><b>Named on their website</b> (no date or amount published): ${named.map(h => esc(h.funder)).join(', ')} ${srcLink(named[0].source)}</p>` : ''}
  ${(() => { const o = H.DIR.find(x => x.id === id), nm = [...new Set(all.map(h => h.recipient))].filter(n => o && n.toLowerCase() !== o.n.toLowerCase()); return nm.length ? `<p class="note">Recorded under the name: ${nm.map(esc).join('; ')}</p>` : ''; })()}
  <p class="note">From published grant records. Amounts and dates are as the source shows them.</p></div>`;
};
const _org = V.org; V.org = id => { const h = _org(id); if (!H.DIR.find(x => x.id === id)) return h; const i = h.lastIndexOf('</div>'); return h.slice(0, i) + `<div style="margin-top:16px">${funderPanel(id)}</div>` + h.slice(i); };
const _page = V.page; V.page = id => { const h = _page(id), oid = id === 'demo' ? null : id; if (!oid || !h.includes('opwrap')) return h; const i = h.lastIndexOf('</div>'); return h.slice(0, i) + `<section class="band" style="padding-top:0">${funderPanel(oid)}</section>` + h.slice(i); };

/* funders active in Luton */
const rankFunders = () => { const by = {};
  FH().filter(h => h.type !== NAMED).forEach(h => { const k = h.funder; const b = by[k] = by[k] || { f: k, orgs: new Set(), recentOrgs: new Set(), amts: [], recs: [] }; b.orgs.add(h.recipient); if (recent(h)) b.recentOrgs.add(h.recipient); if (h.type === 'single grant' && h.amount) b.amts.push(h.amount); if (h.largest) b.amts.push(h.largest); b.recs.push(h); });
  return Object.values(by).sort((a, z) => z.recentOrgs.size - a.recentOrgs.size || z.orgs.size - a.orgs.size); };
V.pastfunders = () => { const rows = rankFunders();
  return `<div class="wrap">${back('funding', 'Funding finder', 'Funders active in Luton')}<h1>Funders active in Luton</h1><p class="lede">Funders that have given grants to Luton organisations, ranked by how many Luton organisations they’ve funded since ${SINCE}. They already know Luton, so they’re a good place to start.</p>
  <p class="note">From published grant records: 360Giving GrantNav, The National Lottery Community Fund, Luton Council’s grants list, local news and organisations’ own pages. Not every grant is published, so treat this as a guide. Amounts shown only where the source publishes them.</p>
  <input class="in" id="pfQ" placeholder="Search funder or organisation" aria-label="Search funders">
  <div class="board notes wide pfl">${rows.map((b, i) => { const live = openFundFor(b.f), lo = b.amts.length ? Math.min(...b.amts) : null, hi = b.amts.length ? Math.max(...b.amts) : null;
    return `<div class="note-card pf" data-pf="${esc((b.f + ' ' + [...b.orgs].join(' ')).toLowerCase())}"><div class="row" style="justify-content:space-between;align-items:flex-start"><h3><span class="note">${i + 1}.</span> ${esc(b.f)}</h3><span class="stamp">${b.recentOrgs.size} since ${SINCE}</span></div>
    <p class="note">${b.orgs.size} Luton organisation${b.orgs.size === 1 ? '' : 's'} in the records${lo ? ` · published grants from ${gbp(lo)} to ${gbp(hi)}` : ''}</p>
    <details><summary>Who they funded</summary><ul class="pfr">${b.recs.slice(0, 12).map(h => `<li><b>${esc(h.recipient)}</b> · ${esc(whenTxt(h) || String(h.year || ''))}${h.amount ? ' · ' + gbp(h.amount) : ''}${h.grants > 1 ? ' (' + h.grants + ' grants)' : ''} ${srcLink(h.source)}</li>`).join('')}${b.recs.length > 12 ? `<li class="note">+ ${b.recs.length - 12} more</li>` : ''}</ul></details>
    ${live ? `<a class="btn s sm" href="#funding">Open now: ${esc(live.n)}</a>` : ''}</div>`; }).join('')}</div>${L.POWERED || ''}</div>`; };

/* sponsorship */
const SP_OFFER = [['i_printnib', 'Logo on your materials', 'Banners, shirts, posters and social posts'], ['i_flag', 'Naming rights', '“The Summer Club, supported by…” for a programme or event'], ['i_megaphone', 'Social media thank-yous', 'Posts and stories that feature them'], ['i_magazine', 'Newsletter and website', 'A mention and logo where your community looks'], ['i_handheart', 'Staff volunteering days', 'Their team helps out for a day'], ['i_venuekey', 'A stall at your event', 'Meet the people they want to reach'], ['i_people', 'A speaking slot', 'A few words at your event or assembly'], ['i_report', 'Impact report with photos', 'What their money made happen'], ['i_award', 'Certificate or plaque', 'Something to put on their wall'], ['i_tag', '“Proud supporter” sticker', 'For their window or counter'], ['i_pen', 'Local press release', 'A story for local papers and radio']];
