const gi = (g, cls = 'ti sm') => `<svg class="${cls}" viewBox="0 0 48 48" aria-hidden="true"><rect width="48" height="48" rx="13" fill="var(--soft, #EEEDF8)"/><g transform="translate(10.5 10.5) scale(1.125)" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="${L.GLYPH[g] || L.GLYPH.plus}"/></g></svg>`;
V.sponsor = () => `<div class="wrap">${back('fundsup', 'Funding support', 'Sponsorship')}<div class="sec-h"><div><h1>Sponsorship</h1><p class="lede">Get local businesses behind your events and programmes. What to offer, how to make it worth their while, and how to ask, with wording you can copy.</p></div><div class="row"><button class="btn p" data-spck>${si('check')} Sponsorship pack checklist</button></div></div>
  <section class="band" style="padding-top:0"><div class="two" style="align-items:start"><div class="dlbox"><h3>What sponsorship is</h3><p>A business gives money, goods or time, and gets something back: visibility, goodwill, a link with the community. It’s a deal, so it’s agreed in advance.</p><ul class="ticks"><li><b>Donation:</b> a gift, nothing expected back.</li><li><b>Grant:</b> from a funder, with an application and reporting.</li><li><b>Sponsorship:</b> from a business, with something agreed in return.</li></ul></div>
  <div class="dlbox"><h3>When it works well</h3><ul class="ticks"><li>Events: fun days, iftars, sports days, awards nights</li><li>Programmes: holiday clubs, youth sessions, classes</li><li>Kit and equipment: shirts, laptops, gazebos</li><li>Awards and prizes</li><li>Campaigns and appeals with a clear goal</li></ul></div></div></section>
  <section class="band"><h2>What you can offer sponsors</h2><p class="note">Pick what fits. You don’t need to offer everything.</p><div class="lptiles sptiles">${SP_OFFER.map(([g, t, d]) => `<div class="lptile sptile">${gi(g)}<span><b>${t}</b><small>${d}</small></span></div>`).join('')}</div></section>
  <section class="band"><h2>Package ideas</h2><p class="note">You set your own amounts, based on your costs and what you can deliver.</p><div class="grid">${SP_TIERS.map(([t, d, l]) => `<div class="card"><span class="tag ex">Example</span><h3>${t}</h3><p>${d}</p><ul class="ticks">${l.map(x => `<li>${x}</li>`).join('')}</ul></div>`).join('')}</div></section>
  <section class="band"><h2>Make it worth it for the sponsor</h2><div class="board notes wide">${SP_VALUE.map(([t, d]) => `<div class="note-card"><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></section>
  <section class="band"><h2>How to approach businesses</h2><ol class="spsteps">${SP_STEPS.map(([t, d], i) => `<li><b>${i + 1}. ${t}</b><p>${d}</p></li>`).join('')}</ol><p class="note">Keep it personal. A handful of well-chosen, polite asks works far better than mass emails, and it protects your organisation’s name.</p></section>
  <section class="band"><h2>Wording you can copy</h2><p class="note">Change the parts in [brackets] before you send.</p><div class="grid">${Object.entries(SP_T).map(([k, [t, b]]) => `<div class="dlbox"><h3>${t}</h3><div class="msg" id="spT_${k}" style="white-space:pre-wrap">${esc(b)}</div><div class="row" style="margin-top:8px">${copyBtn('#spT_' + k)}</div></div>`).join('')}</div></section>
  <section class="band"><div class="feature"><h2>How SMR Digital can help</h2><p>Optional, at community rates. You give us the details; we design it to match your brand. Nothing is printed or ordered until you approve the proof in writing.</p><ul class="ticks two-col"><li>Sponsorship pack and one-page proposal</li><li>Banners and roller banners with sponsor logos</li><li>Shirts and printed kit</li><li>Social media thank-you posts</li><li>Certificates and plaques</li><li>“Proud supporter” window stickers</li><li>Event photos and short videos</li><li>Impact report design</li></ul><div class="row"><button class="btn w" data-xq="sponsor-design">Ask us to help</button><a class="btn o" href="#studio">See the studio</a></div></div></section>
  ${L.POWERED || ''}</div>`;
XQ['sponsor-design'] = ['Help with your sponsorship materials', 'Tell us what you need. We’ll reply with ideas and a community-rate quote. Once you go ahead it appears in Design jobs, and nothing is printed until you approve the proof in writing.', [['org', 'Organisation'], ['project', 'Project or event'], ['need', 'What do you need? (pack, banners, shirts, posts, certificates, stickers, photos, report)', 'ta'], ['when', 'When do you need it?'], ['contact', 'Best contact']]];
