const KEYDATES = [['2027-02-08', 'Ramadan expected to start (around 8 Feb 2027)'], ['2027-03-10', 'Eid al-Fitr expected (around 10 Mar 2027)'], ['2027-05-17', 'Eid al-Adha expected (around 17 May 2027)'], ['2026-12-25', 'Christmas Day'], ['2026-12-26', 'Boxing Day'], ['2027-01-01', 'New Year’s Day'], ['2027-03-26', 'Good Friday'], ['2027-03-29', 'Easter Monday'], ['2027-05-03', 'Early May bank holiday'], ['2027-05-31', 'Spring bank holiday'], ['2027-08-30', 'Summer bank holiday']];
const clashTool = () => { const s = store.get('clash', {}); return `<section class="toolsec" id="clashT"><h2>Clash checker</h2><p class="note">Pick a date to see what else is on nearby, before you fix yours.</p><form class="row" id="clashF" onsubmit="return false"><label class="f sm">Date<input class="in" type="date" name="d" value="${esc(s.d || '')}"></label><label class="f sm">Area<select class="in" data-ux-keep name="a"><option value="">Anywhere in Luton</option>${['LU1', 'LU2', 'LU3', 'LU4'].map(x => `<option ${s.a === x ? 'selected' : ''}>${x}</option>`).join('')}</select></label></form><div id="clashOut">${clashOut(s)}</div></section>`; };
const clashOut = s => { if (!s.d) return ''; const d0 = new Date(s.d), near = d => Math.abs((new Date(d) - d0) / 864e5) <= 2;
  const ev = [...(H.EV || []).map(e => ({ t: e.t, s: e.s, w: e.where || '', pc: e.pc || '' })), ...((L.appr?.('event') || []).map(x => ({ t: x.data.title, s: x.data.date, w: x.data.where || '', pc: x.data.where || '' })))].filter(e => e.s && near(e.s) && (!s.a || !e.pc || String(e.pc).toUpperCase().startsWith(s.a)));
  const kd = KEYDATES.filter(([d]) => near(d)), fri = d0.getDay() === 5;
  return `<div class="toolres">${ev.length || kd.length || fri ? `${listItems([...kd.map(([d, t]) => `<b>${esc(t)}</b><span class="note"> · ${new Date(d).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' })}</span>`), ...(fri ? ['<b>It’s a Friday</b><span class="note"> · avoid Jummah time (around 12:30 to 2pm) if Muslim families are coming</span>'] : []), ...ev.map(e => `<b>${esc(e.t)}</b><span class="note"> · ${new Date(e.s).toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' })} · ${esc(e.w)}</span>`)], x => `<li>${x}</li>`)}` : '<p><b>Looks clear.</b> Nothing else listed within two days. Add your dates so others can see them.</p>'}<div class="row"><button class="btn s sm" data-calpost>Add your dates</button></div><p class="note">Islamic dates are expected dates and depend on the moon sighting.</p></div>`; };
