document.addEventListener('change', e => { const f = e.target.closest('#clashF'); if (!f) return; const s = Object.fromEntries(new FormData(f)); store.set('clash', s); const o = document.getElementById('clashOut'); if (o) o.innerHTML = clashOut(s); });

