  if (r.v === 'help') { const wt = $('.winter h2', w); if (wt && !$('.winter .passon', w)) wt.insertAdjacentHTML('afterend', `<p class="passon">${si('share')}<span>Warm spaces and winter help to pass on to anyone struggling this winter.</span></p>`); }
